sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
	var isEmergency = (newValue == 'true' || newValue == true);

	if(isEmergency) {
		return;
	}

	var startDateStr = g_form.getValue('start_date');
	var selectedDate = getDateFromFormat(startDateStr, g_user_date_format);
	var currentDate = new Date().toISOString().slice(0, 10);

	if(selectedDate < currentDate) {
		g_form.showErrorBox('start_date', 'Start Date must not be in the past unless Emergency Leave is checked.', 'error');
		g_form.setValue('start_date', '');
	}
}
